namespace VietCommerce.Core.DTOs.Rituals
{
    /// <summary>
    /// DTO for FE-AI explanation output generated by Gemini API
    /// </summary>
    public class ExplanationPayloadDto
    {
        /// <summary>
        /// Name of the ritual being explained
        /// </summary>
        public string RitualName { get; set; } = string.Empty;

        /// <summary>
        /// Cultural context and significance of the ritual
        /// </summary>
        public string CulturalContext { get; set; } = string.Empty;

        /// <summary>
        /// Explanations for each recommended item
        /// </summary>
        public List<ItemExplanationDto> ItemExplanations { get; set; } = new();

        /// <summary>
        /// Sources or references supporting the explanation
        /// </summary>
        public List<string> Sources { get; set; } = new();

        /// <summary>
        /// Indicates whether explanation was generated by Gemini or fallback template
        /// </summary>
        public string GeneratedBy { get; set; } = "gemini";
    }

    /// <summary>
    /// DTO for explanation of a single recommended item
    /// </summary>
    public class ItemExplanationDto
    {
        /// <summary>
        /// Product ID being explained
        /// </summary>
        public Guid ProductId { get; set; }

        /// <summary>
        /// Product name
        /// </summary>
        public string ProductName { get; set; } = string.Empty;

        /// <summary>
        /// Why this item is needed for the ritual
        /// </summary>
        public string WhyNeeded { get; set; } = string.Empty;

        /// <summary>
        /// Traditional usage and cultural significance of the item
        /// </summary>
        public string TraditionalUsage { get; set; } = string.Empty;
    }
}
